`,i=[[-150,-120,260],[140,-150,-220],[-90,-190,180],[170,-40,-300],[-180,-10,240],[60,-210,-160],[-40,120,200],[120,90,-260]],g={"soft-a":{disk:"#f1a0ad",ring:"#f8cdd5",seam:"#e7a3b0",petals:["#f1a0ad","#f6c6cf","#f3d68f"]},"soft-c":{disk:"#92b5e0",ring:"#c9daf1",seam:"#a9c3e8",petals:["#f1a0ad","#92b5e0","#82c8a9","#f3d68f"]}},c=d=>`
